362	// Request is one resolution request: an HTTP method and a request target
363	// (path with an optional raw query string).
364	type Request struct {
365		Method string `json:"method"`
366		Target string `json:"target"`
367	}
368	
369	// Resolution is the successful result of matching a request.
370	type Resolution struct {
371		RouteID     string `json:"routeId"`
372		UpstreamURL string `json:"upstreamURL"`
373	}
