package main

import (
	"encoding/json"
	"fmt"

	"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

func main() {
	src := `{
  "routes": [
    {"id":"r1","methods":["get","POST"],"pathPrefix":"/a%20b","upstream":"http://h.internal/base/",
     "queryTransforms":[
       {"op":"rename","name":"old 名","to":"n+w%"},
       {"op":"set","name":"a&b=c","value":""},
       {"op":"set","name":"k","value":"中文 +%2f"},
       {"op":"remove","name":"flag"}
     ]},
    {"id":"r2","methods":["*"],"pathPrefix":"/b","upstream":"https://h2:8443/x","queryTransforms":[]}
  ]
}`
	cfg, f := contractsentinel.ParseConfig([]byte(src))
	if f != nil {
		panic(f.Error())
	}
	out, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		panic(err)
	}
	fmt.Println(string(out))

	cfg2, f := contractsentinel.ParseConfig(out)
	if f != nil {
		panic("reparse failed: " + f.Error())
	}

	targets := []string{
		"/a%20b/p?old%20%E5%90%8D=1&a%26b%3dc=9&flag&z=2",
		"/a%20b/p?x=%2f&a=1&%61=2&flag",
		"/a%20b/?",
	}
	for _, t := range targets {
		req, rf := contractsentinel.ParseRequest([]byte(`{"method":"get","target":"` + t + `"}`))
		if rf != nil {
			panic(rf.Error())
		}
		r1, e1 := contractsentinel.Resolve(cfg, req)
		req2, _ := contractsentinel.ParseRequest([]byte(`{"method":"get","target":"` + t + `"}`))
		r2, e2 := contractsentinel.Resolve(cfg2, req2)
		if (e1 == nil) != (e2 == nil) || e1 != nil && e1.Code != e2.Code {
			panic(fmt.Sprintf("error mismatch for %s:\n%v\n%v", t, e1, e2))
		}
		if e1 == nil && (r1.RouteID != r2.RouteID || r1.UpstreamURL != r2.UpstreamURL) {
			panic(fmt.Sprintf("mismatch for %s:\n%s %s\n%s %s", t, r1.RouteID, r1.UpstreamURL, r2.RouteID, r2.UpstreamURL))
		}
		if e1 != nil {
			fmt.Printf("%s -> %s (both)\n", t, e1.Code)
		} else {
			fmt.Printf("%s -> %s %s (equal)\n", t, r2.RouteID, r2.UpstreamURL)
		}
	}
}
EOF
